[
  {
    "id": "PUB-01",
    "brief": "A",
    "family": "Happy path",
    "level": "easy",
    "title": "Confirms identity and pays the full amount today",
    "variables": {
      "first_name": "Daniel",
      "last_name": "Reyes",
      "title": "Mr",
      "now": "2026-10-14T11:00"
    },
    "identity": {
      "date_of_birth": "1988-03-14",
      "phone_last4": "4471"
    },
